378	// Resubmitting the same id with the same request — including the same
379	// optional hash — returns the stored job; the same id with different content
380	// yields ErrConflict, reported before any artifact check of the new request.
381	// A stored job stays pinned to the version submitted, regardless of circuit
382	// versions added later.
383	func (s *Store) SubmitJob(job Job) (Job, error) {
384		if strings.TrimSpace(job.ID) == "" {
385			return Job{}, invalidf("job id must be non-empty and not only whitespace")
386		}
387		if strings.TrimSpace(job.Circuit) == "" {
388			return Job{}, invalidf("job %q must name a circuit", job.ID)
389		}
390		if job.Version <= 0 {
391			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
392		}
393		if job.Attempt <= 0 {
394			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
395		}
396		if job.Kind != "prove" {
397			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
398				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
399		}
400	
401		var result Job
402		err := s.withLock(func() (bool, error) {
403			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
404				if !sameJobRequest(*existing, job) {
405					return false, conflictf("job %q already exists with a different request", job.ID)
406				}
407				result = jobFromPersist(*existing)
408				return false, nil
409			}
410			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
411			if circuit == nil {
412				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
413			}
414			if !circuit.Frozen {
415				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
416			}
417			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
418				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
419					job.ID, job.Circuit, job.Version)
420			}
421			if job.CompiledHash != "" {
422				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
423				if artifact == nil {
424					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
425						job.ID, job.Circuit, job.Version)
426				}
427				if artifact.Hash != job.CompiledHash {
428					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
429						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
430				}
431			}
432			record := persistJob{
433				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
434				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
435				CompiledHash: job.CompiledHash,
436			}
437			s.data.Jobs = append(s.data.Jobs, record)
438			result = jobFromPersist(record)
439			return true, nil
440		})
441		return result, err
442	}
443	
444	// GetCircuit returns one circuit version, sorted-field populated exactly as
445	// stored. Unknown versions yield ErrNotFound.
446	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
447		if err := validateCircuitKey(name, version); err != nil {
448			return Circuit{}, err
449		}
450		var result Circuit
451		err := s.withLockRead(func() error {
452			existing := findCircuit(s.data.Circuits, name, version)
453			if existing == nil {
454				return notFoundf("circuit %q version %d does not exist", name, version)
455			}
456			result = circuitFromPersist(*existing)
457			return nil
458		})
459		return result, err
460	}
461	
462	// ListCircuits returns all stored circuit versions ordered by circuit name
463	// (lexicographically) and then by ascending version number.
464	func (s *Store) ListCircuits() ([]Circuit, error) {
465		var result []Circuit
466		err := s.withLockRead(func() error {
467			ordered := append([]persistCircuit(nil), s.data.Circuits...)
468			sort.Slice(ordered, func(i, j int) bool {
469				if ordered[i].Name != ordered[j].Name {
470					return ordered[i].Name < ordered[j].Name
471				}
472				return ordered[i].Version < ordered[j].Version
473			})
474			result = make([]Circuit, len(ordered))
475			for i, c := range ordered {
476				result[i] = circuitFromPersist(c)
477			}
478			return nil
479		})
480		return result, err
481	}
482	
483	// GetSetup reports whether a trusted setup is registered for the named
484	// frozen version. A missing record yields ErrNotFound.
485	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
486		if err := validateCircuitKey(name, version); err != nil {
487			return Setup{}, false, err
488		}
489		var result Setup
490		found := false
491		err := s.withLockRead(func() error {
492			existing := findSetup(s.data.Setups, name, version)
493			if existing == nil {
494				return nil
495			}
496			result = setupFromPersist(*existing)
497			found = true
498			return nil
499		})
500		return result, found, err
501	}
502	
503	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
504	func (s *Store) GetJob(id string) (Job, error) {
505		if strings.TrimSpace(id) == "" {
506			return Job{}, invalidf("job id must be non-empty and not only whitespace")
507		}
508		var result Job
509		err := s.withLockRead(func() error {
510			existing := findJob(s.data.Jobs, id)
511			if existing == nil {
512				return notFoundf("job %q does not exist", id)
513			}
514			result = jobFromPersist(*existing)
515			return nil
516		})
517		return result, err
518	}
519	
520	// ListJobs returns all accepted jobs ordered by job id lexicographically.
521	func (s *Store) ListJobs() ([]Job, error) {
522		var result []Job
523		err := s.withLockRead(func() error {
524			ordered := append([]persistJob(nil), s.data.Jobs...)
525			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
526			result = make([]Job, len(ordered))
527			for i, j := range ordered {
528				result[i] = jobFromPersist(j)
529			}
530			return nil
531		})
532		return result, err
533	}
534	
535	// --- validation helpers ---------------------------------------------------
536	
537	func validateCircuitKey(name string, version int) error {
538		if strings.TrimSpace(name) == "" {
539			return invalidf("circuit name must be non-empty and not only whitespace")
540		}
541		if version <= 0 {
542			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
543		}
544		return nil
545	}
546	
547	// maxInputWires is the largest declared input count that stays representable
548	// on the running platform. Wire numbering always reserves wire 0 for the
549	// constant one, so the wires a version names are 0 plus its public and private
550	// inputs: the declared counts must satisfy 1 + public + private <= M, where M
551	// is the largest positive value the platform's int can hold. The check is done
552	// without ever adding the counts, so a layout whose sum would wrap (e.g.
553	// public=M with one private input) is refused rather than accepted through
554	// integer wraparound as a small, representable layout.
555	const maxInputWires = math.MaxInt
556	
557	// inputLayoutRepresentable reports whether the constant wire plus the public
558	// and private inputs fits inside the platform's int. Callers already guarantee
559	// both counts are non-negative.
560	func inputLayoutRepresentable(publicInputs, privateInputs int) bool {
561		return publicInputs <= maxInputWires-1 && privateInputs <= maxInputWires-1-publicInputs
562	}
563	
564	func validateCounts(constraints, publicInputs, privateInputs int) error {
565		if constraints <= 0 {
566			return invalidf("constraints must be greater than zero, got %d", constraints)
567		}
568		if publicInputs < 0 {
569			return invalidf("public input count must not be negative, got %d", publicInputs)
570		}
571		if privateInputs < 0 {
572			return invalidf("private input count must not be negative, got %d", privateInputs)
573		}
574		if !inputLayoutRepresentable(publicInputs, privateInputs) {
575			return invalidf("input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
576				publicInputs, privateInputs, maxInputWires)
577		}
578		return nil
579	}
580	
581	// --- lookup / mapping helpers --------------------------------------------
582	
583	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
584		for i := range cs {
585			if cs[i].Name == name && cs[i].Version == version {
586				return &cs[i]
587			}
588		}
589		return nil
590	}
591	
592	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
593		for i := range ps {
594			if ps[i].Name == name && ps[i].Version == version {
595				return &ps[i]
596			}
597		}
598		return nil
599	}
600	
601	func findJob(js []persistJob, id string) *persistJob {
602		for i := range js {
603			if js[i].ID == id {
604				return &js[i]
605			}
606		}
607		return nil
608	}
609	
610	func sameJobRequest(stored persistJob, request Job) bool {
611		return stored.Circuit == request.Circuit &&
612			stored.Version == request.Version &&
613			stored.Kind == request.Kind &&
614			stored.Attempt == request.Attempt &&
615			stored.CompiledHash == request.CompiledHash
616	}
617	
618	func circuitFromPersist(c persistCircuit) Circuit {
619		return Circuit{
620			Name: c.Name, Version: c.Version,
621			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
622			Frozen: c.Frozen, Description: c.Description,
623		}
624	}
625	
626	// circuitCopyMatches reports whether target is the same draft content that a
627	// copy of source would create: same description, same three counts and a
628	// semantically equal constraint definition. Definition equality follows the
629	// existing normalization semantics (terms merged per wire, coefficients
630	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
631	// definition differs from a present one.
632	func circuitCopyMatches(source, target persistCircuit) bool {
633		if source.Description != target.Description {
634			return false
635		}
636		if source.Constraints != target.Constraints ||
637			source.PublicInputs != target.PublicInputs ||
638			source.PrivateInputs != target.PrivateInputs {
639			return false
640		}
641		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
642	}
643	
644	// definitionsEqual compares two stored definitions for semantic equality.
645	// Both nil is equal; one nil and the other not is different. When both are
646	// present they are parsed through the existing normalization pipeline and
647	// compared by modulus, constraint count and each side's wire/coefficient
648	// pairs. The public/private layout is the source's; the caller has already
649	// confirmed the counts match.
650	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
651		if d1 == nil && d2 == nil {
652			return true
653		}
654		if d1 == nil || d2 == nil {
655			return false
656		}
657		p1, err := definitionFromPersist(*d1, public, private)
658		if err != nil {
659			return false
660		}
661		p2, err := definitionFromPersist(*d2, public, private)
662		if err != nil {
663			return false
664		}
665		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
666			return false
667		}
668		for i := range p1.constraints {
669			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
670				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
671				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
672				return false
673			}
674		}
675		return true
676	}
677	
678	// canonicalTermsEqual reports whether two normalized term slices are
679	// identical wire-by-wire and coefficient-by-coefficient.
680	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
681		if len(t1) != len(t2) {
682			return false
683		}
684		for i := range t1 {
685			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
686				return false
687			}
688		}
689		return true
690	}
691	
692	func setupFromPersist(p persistSetup) Setup {
693		return Setup{Name: p.Name, Version: p.Version}
694	}
695	
696	func jobFromPersist(j persistJob) Job {
697		return Job{
698			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
699			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
700			CompiledHash: j.CompiledHash,
701		}
702	}
