1	package zkcircuit
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7	)
8	
9	// This file holds the constraint lifecycle operations: importing a draft
10	// definition from a JSON file, compiling a frozen version into a hashed
11	// artifact, and checking an input assignment against an artifact.
12	
13	// ImportConstraints reads a definition JSON file and stores it for one draft
14	// circuit version, replacing any previously imported definition as a whole.
15	//
16	// The version must exist and be a draft; a frozen version's definition can
17	// never be replaced (ErrFrozen). The file is parsed and fully validated
18	// against the version's declared counts before anything is committed, so a
19	// rejected import leaves the previous definition byte-for-byte in place.
20	// Unknown versions yield ErrNotFound; malformed or illegal definitions
21	// yield ErrInvalidArgument.
22	func (s *Store) ImportConstraints(name string, version int, path string) (Definition, error) {
23		if err := validateCircuitKey(name, version); err != nil {
24			return Definition{}, err
25		}
26		raw, err := os.ReadFile(path)
27		if err != nil {
28			return Definition{}, invalidf("cannot read constraint definition file %q: %v", path, err)
29		}
30	
31		var result Definition
32		err = s.withLock(func() (bool, error) {
33			circuit := findCircuit(s.data.Circuits, name, version)
34			if circuit == nil {
35				return false, notFoundf("circuit %q version %d does not exist", name, version)
36			}
37			if circuit.Frozen {
38				return false, frozenf("circuit %q version %d is frozen; its constraint definition cannot be replaced", name, version)
39			}
40			parsed, perr := parseDefinitionJSON(raw, circuit.PublicInputs, circuit.PrivateInputs, circuit.Constraints)
41			if perr != nil {
42				return false, perr
43			}
44			persisted := parsed.toPersist()
45			circuit.Definition = &persisted
46			result = parsed.toExport()
47			return true, nil
48		})
49		return result, err
50	}
51	
52	// GetDefinition returns the imported definition of one version. A version
53	// without one yields ErrDefinitionMissing, and an unknown version
54	// ErrNotFound.
55	func (s *Store) GetDefinition(name string, version int) (Definition, error) {
56		if err := validateCircuitKey(name, version); err != nil {
57			return Definition{}, err
58		}
59		var result Definition
60		err := s.withLockRead(func() error {
61			circuit := findCircuit(s.data.Circuits, name, version)
62			if circuit == nil {
63				return notFoundf("circuit %q version %d does not exist", name, version)
64			}
65			if circuit.Definition == nil {
66				return definitionMissingf("circuit %q version %d has no constraint definition", name, version)
67			}
68			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
69			if perr != nil {
70				return corruptf("circuit %q v%d stored definition cannot be read: %v", name, version, perr)
71			}
72			result = parsed.toExport()
73			return nil
74		})
75		return result, err
76	}
77	
78	// CompileCircuit compiles a frozen circuit version into an artifact.
79	//
80	// Only frozen versions compile: unknown versions yield ErrNotFound, drafts
81	// ErrNotFrozen. A version whose counts were registered but which never had a
82	// definition imported yields ErrDefinitionMissing. Repeated compilation of
83	// the same version is idempotent and returns the identical artifact; other
84	// versions' artifacts are unaffected.
85	func (s *Store) CompileCircuit(name string, version int) (Artifact, error) {
86		if err := validateCircuitKey(name, version); err != nil {
87			return Artifact{}, err
88		}
89		var result Artifact
90		err := s.withLock(func() (bool, error) {
91			circuit := findCircuit(s.data.Circuits, name, version)
92			if circuit == nil {
93				return false, notFoundf("circuit %q version %d does not exist", name, version)
94			}
95			if !circuit.Frozen {
96				return false, notFrozenf("circuit %q version %d must be frozen before compilation", name, version)
97			}
98			if existing := findArtifact(s.data.Artifacts, name, version); existing != nil {
99				result = artifactFromPersist(*existing)
100				return false, nil
101			}
102			if circuit.Definition == nil {
103				return false, definitionMissingf("circuit %q version %d has only registered counts and no constraint definition; import one before freezing",
104					name, version)
105			}
106			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
107			if perr != nil {
108				return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
109			}
110			if !parsed.compatibleWith(circuit.Constraints, circuit.PublicInputs, circuit.PrivateInputs) {
111				return false, corruptf("stored definition for %q v%d no longer matches its declared counts", name, version)
112			}
113			record := persistArtifact{
114				Name:        name,
115				Version:     version,
116				Modulus:     parsed.modulus,
117				Constraints: len(parsed.constraints),
118				Hash:        artifactHash(name, version, parsed),
119			}
120			s.data.Artifacts = append(s.data.Artifacts, record)
121			result = artifactFromPersist(record)
122			return true, nil
123		})
124		return result, err
125	}
126	
127	// GetArtifact returns the compiled artifact for one version. A version
128	// without one yields ErrArtifactMissing, and an unknown version ErrNotFound.
129	func (s *Store) GetArtifact(name string, version int) (Artifact, error) {
130		if err := validateCircuitKey(name, version); err != nil {
131			return Artifact{}, err
132		}
133		var result Artifact
134		err := s.withLockRead(func() error {
